vector<string> generate_all_possible_strings(string s) {
    vector<string> result;
    for (int i = 0; i < s.size(); i++) {
        string curr = s.substr(0, i) + "A" + s.substr(i);
        result.push_back(curr);
    }
    return result;
}

int solve(string s, int k) {
    vector<string> all_possible_strings = generate_all_possible_strings(s);
    int min_ops = 10000;
    int curr_ops = 0;
    for (string curr : all_possible_strings) {
        int count = 0;
        for (char c : curr) {
            if (c == 'B') count++;
        }
        if (count == k) {
            min_ops = min(min_ops, ++curr_ops);
        }
    }
    return min_ops;
}

