// Given a positive integer of length n and an additional digit (0-9), find the maximum possible integer that can be obtained by inserting this digit into the initial number, in two possible ways (e.g. after the 3rd or 4th digit).

// Output: A string of length n+1 representing the maximum possible integer.

// Constraints:
// - The input integer can have leading zeros.
// - The additional digit is guaranteed to be non-negative.
// - The length of the initial integer is between 1 and 2 * 10^5, inclusive.

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n, d;
        string s;
        cin >> n >> d;
        cin >> s;
        string r1 = maxPossibleInteger(n, s, d);
        string r2 = maxPossibleInteger(n, s, d*10);
        cout << max(r1, r2) << "\n";
    }
    return 0;
}

string maxPossibleInteger(int n, string s, int d) {
    string res = "0";
    for (int i = 0; i < n; i++) {
        string t1 = s.substr(0, i) + to_string(d) + s.substr(i);
        string t2 = s.substr(0, i+1) + to_string(d*10) + s.substr(i);
        res = max(res, max(t1, t2));
    }
    return res;
}

