	n = len(numbers)

	# if the sum of all elements in the list is already 0, return -1
	if sum(numbers) == 0:
		return -1

	# if the list contains a 0, return 0
	if 0 in numbers:
		return 0

	# iterate through the list and find the first element that is not a power of 2
	for i, num in enumerate(numbers):
		if num & (num - 1) == 0:
			continue
		else:
			# if the element is not a power of 2, return the XOR of it and all other elements
			return sum(chain([num], numbers[i + 1:]))

