int solve(int n, int m, int x1, int y1, int x2, int y2) {
    if (x1 == x2 && y1 == y2) {
        return 0;
    }

    int dirs[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
    bool visited[n][m];
    memset(visited, false, sizeof(visited));
    visited[x1][y1] = true;

    int min_obstacles = 0;
    while (!visited[x2][y2]) {
        min_obstacles++;
        for (int i = 0; i < 4; i++) {
            int new_x = x2 + dirs[i][0];
            int new_y = y2 + dirs[i][1];
            if (new_x >= 0 && new_x < n && new_y >= 0 && new_y < m && !visited[new_x][new_y]) {
                visited[new_x][new_y] = true;
                x2 = new_x;
                y2 = new_y;
                break;
            }
        }
    }

    return min_obstacles;
}

