def solve(n: int) -> List[int]:
  queue = Queue()
  queue.enqueue(Node(0, [i for i in range(1, n + 1)]))

  while queue.queue:
    node = queue.dequeue()
    if len(node.value) == n:
      return node.value

    for i in range(1, n):
      if i != node.value[i]:
        new_node = Node(node.position + 1, node.value.copy())
        new_node.value[i], new_node.value[node.value[i]] = node.value[node.value[i]], node.value[i]
        queue.enqueue(new_node)

  raise ValueError("Could not find a solution")

