               num_non_empty_cells += 1

   # If there are no non-empty cells, return 0
   if num_non_empty_cells == 0:
       return 0

   # Find the minimum number of moves required to cut all non-empty cells
   min_moves = float('inf')
   for i in range(2):
       for j in range(2):
           # Count the number of non-empty cells in this row and column
           num_non_empty_cells_in_row = 0
           for k in range(2):
               if a[i][k] == 1:
                   num_non_empty_cells_in_row += 1
           num_non_empty_cells_in_col = 0
           for k in range(2):
               if a[k][j] == 1:
