           moves_in_row = num_non_empty_cells_in_row - 1
           moves_in_col = num_non_empty_cells_in_col - 1
           moves = moves_in_row + moves_in_col

           # Update the minimum number of moves
           if moves < min_moves:
               min_moves = moves

   return min_moves

